def retain_legacy_states(apps, schema_editor):
    Application = apps.get_model('programs', 'ProgramApplication')
    Case = apps.get_model('assistance', 'AssistanceCase')
    Release = apps.get_model('assistance', 'AssistanceRelease')
    alias = schema_editor.connection.alias
    for application in Application.objects.using(alias).all().iterator():
        original = application.status
        state = 'CLOSED' if original == 'cancelled' else 'NEEDS_INFORMATION'
        case = Case.objects.using(alias).filter(application_id=application.pk).first()
        if Release.objects.using(alias).filter(application_id=application.pk, voided_at__isnull=True).exists():
            state = 'COMPLETED'
        elif case and case.decision in ('approved', 'rejected'):
            state = 'SELECTED' if case.decision == 'approved' else 'NOT_SELECTED'
        # No legacy application receives a fabricated photo or eligibility review.
        Application.objects.using(alias).filter(pk=application.pk).update(legacy_status=original, status=state)


